ALTER TABLE public.user_roles ADD COLUMN can_dispatch_jobs boolean;
COMMENT ON COLUMN public.user_roles.can_dispatch_jobs IS 'Per-member permission to schedule jobs; separate from eligibility to work in the field. Null keeps manager role defaults.';
CREATE OR REPLACE FUNCTION public.member_dispatch_can() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.company_id=public.current_company_id() AND public.member_is_active(r.user_id) AND coalesce(r.can_dispatch_jobs,r.role IN ('superuser','admin','supervisor'))) $$;
REVOKE ALL ON FUNCTION public.member_dispatch_can() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.member_dispatch_can() TO authenticated;
CREATE OR REPLACE FUNCTION public.my_member_capabilities() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('estimates',public.member_commercial_can('estimates'),'contracts',public.member_commercial_can('contracts'),'dispatch',public.member_dispatch_can()) $$;
CREATE OR REPLACE FUNCTION public.set_member_dispatch(_user uuid,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.user_roles; BEGIN SELECT * INTO r FROM public.user_roles WHERE user_id=_user AND company_id=public.current_company_id() FOR UPDATE;
IF NOT FOUND OR auth.uid() IS NULL OR NOT public.member_is_active(auth.uid()) OR NOT(public.my_role()='superuser' OR (public.my_role()='admin' AND r.role<>'superuser')) THEN RAISE EXCEPTION 'Company office admin access required'; END IF;
UPDATE public.user_roles SET can_dispatch_jobs=_enabled WHERE user_id=_user AND company_id=public.current_company_id(); END $$;
REVOKE ALL ON FUNCTION public.set_member_dispatch(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_member_dispatch(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_individual_dispatch_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NOT NULL AND (TG_OP='INSERT' AND NEW.can_dispatch_jobs IS NOT NULL OR TG_OP='UPDATE' AND NEW.can_dispatch_jobs IS DISTINCT FROM OLD.can_dispatch_jobs) AND NOT(NEW.company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND (public.my_role()='superuser' OR public.my_role()='admin' AND NEW.role<>'superuser')) THEN RAISE EXCEPTION 'Company office admin access required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_individual_dispatch_access BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.guard_individual_dispatch_access();
CREATE POLICY individual_dispatch_access ON public.jobs FOR ALL TO authenticated USING(company_id=public.current_company_id() AND public.member_dispatch_can()) WITH CHECK(company_id=public.current_company_id() AND public.member_dispatch_can());
CREATE OR REPLACE FUNCTION public.guard_dispatch_workspace_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
IF TG_OP='DELETE' THEN IF NOT public.member_dispatch_can() THEN RAISE EXCEPTION 'Dispatch capability required'; END IF; RETURN OLD; END IF;
IF TG_OP='INSERT' THEN
-- An estimating member may create only the accepted quote-linked visit through the guarded atomic quote RPC.
IF NOT public.member_dispatch_can() AND NOT(NEW.customer_quote_id IS NOT NULL AND public.member_commercial_can('estimates') AND EXISTS(SELECT 1 FROM public.customer_quotes q WHERE q.id=NEW.customer_quote_id AND q.company_id=NEW.company_id AND q.status='accepted' AND q.job_id IS NULL)) THEN RAISE EXCEPTION 'Dispatch capability required'; END IF;
ELSIF (NEW.scheduled_date IS DISTINCT FROM OLD.scheduled_date OR NEW.window_start IS DISTINCT FROM OLD.window_start OR NEW.window_end IS DISTINCT FROM OLD.window_end OR NEW.assigned_technician_id IS DISTINCT FROM OLD.assigned_technician_id OR NEW.secondary_technician_id IS DISTINCT FROM OLD.secondary_technician_id OR NEW.problem_summary IS DISTINCT FROM OLD.problem_summary OR NEW.priority IS DISTINCT FROM OLD.priority OR NEW.required_team_size IS DISTINCT FROM OLD.required_team_size OR NEW.open_to_claim IS DISTINCT FROM OLD.open_to_claim) AND NOT public.member_dispatch_can() THEN
IF NEW.assigned_technician_id IS DISTINCT FROM OLD.assigned_technician_id AND OLD.open_to_claim AND OLD.assigned_technician_id IS NULL AND NEW.assigned_technician_id=auth.uid() THEN RETURN NEW; END IF;
RAISE EXCEPTION 'Dispatch capability required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER individual_dispatch_write BEFORE INSERT OR UPDATE OR DELETE ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.guard_dispatch_workspace_write();
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.guard_job_staffing()'::regprocedure) INTO d;d:=replace(d,'NOT public.is_company_manager()','NOT public.member_dispatch_can()');EXECUTE d; SELECT pg_get_functiondef('public.dispatch_pending_work(uuid,text,jsonb)'::regprocedure) INTO d;d:=replace(d,'NOT public.is_company_manager()','NOT public.member_dispatch_can()');EXECUTE d; END $$;